<?= $this->extend('layouts/asistenciaLayout') ?>
<?= $this->section('title') ?>Servicios por UPSS y establecimiento<?= $this->endSection() ?>
<?= $this->section('content') ?>
<div class="card bg-white p-4" id="eus-app" data-api="<?= site_url('asistencia/gestordb/api/establecimiento-upss-servicios') ?>" data-catalogos="<?= site_url('asistencia/gestordb/api/establecimiento-upss-servicios/catalogos') ?>">
    <div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><h4 class="mb-1 fw-bold">Servicios por UPSS y establecimiento</h4><p class="text-muted small mb-0">Asigne servicios a una UPSS habilitada en cada establecimiento.</p></div><div class="d-flex flex-wrap gap-2 align-items-end"><div><label class="form-label small mb-1" for="filtroEusEst">Establecimiento</label><select id="filtroEusEst" class="form-select form-select-sm" style="min-width:260px"><option value="">Todos los establecimientos</option></select></div><div><label class="form-label small mb-1" for="filtroEusEstado">Estado</label><select id="filtroEusEstado" class="form-select form-select-sm"><option value="">Todos</option><option value="1">Activos</option><option value="0">Inactivos</option></select></div><button id="btnNuevoEus" class="btn btn-primary btn-sm"><i class="ti ti-plus"></i> Nueva asignación</button></div></div>
    <div class="table-responsive"><table id="tablaEus" class="table table-hover align-middle w-100"><thead><tr><th>ID</th><th>Establecimiento</th><th>Red</th><th>UPSS</th><th>Servicio</th><th>Observación</th><th>Estado</th><th>Actualizado</th><th class="text-end">Acciones</th></tr></thead><tbody></tbody></table></div>
</div>
<div class="modal fade" id="modalEus" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 id="tituloEus" class="modal-title">Nuevo servicio de UPSS</h5><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Cerrar"></button></div><form id="formEus"><div class="modal-body"><input type="hidden" id="eus_ide"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><div class="mb-3"><label for="eus_est_ide" class="form-label">Establecimiento</label><select id="eus_est_ide" class="form-select" required><option value="">Seleccione establecimiento...</option></select></div><div class="mb-3"><label for="eus_eup_ide" class="form-label">UPSS asignada al establecimiento</label><select id="eus_eup_ide" name="eus_eup_ide" class="form-select" required disabled><option value="">Seleccione establecimiento primero...</option></select></div><div class="mb-3"><label for="eus_uss_ide" class="form-label">Servicio UPSS</label><select id="eus_uss_ide" name="eus_uss_ide" class="form-select" required disabled><option value="">Seleccione la UPSS primero...</option></select></div><div class="mb-3"><label for="eus_observacion" class="form-label">Observación</label><textarea id="eus_observacion" name="eus_observacion" class="form-control" rows="3" maxlength="60000"></textarea></div><div class="form-check form-switch"><input id="eus_estado" class="form-check-input" type="checkbox" value="1" checked><label for="eus_estado" class="form-check-label">Relación activa</label></div></div><div class="modal-footer"><button type="button" class="btn btn-light btn-sm" data-bs-dismiss="modal">Cancelar</button><button type="submit" id="btnGuardarEus" class="btn btn-primary btn-sm">Guardar</button></div></form></div></div></div>
<?= $this->endSection() ?>
<?= $this->section('pageScripts') ?>
<script>
(()=>{
 const root=document.getElementById('eus-app');if(!root)return;const api=root.dataset.api,csrfName='<?= csrf_token() ?>';let csrfHash='<?= csrf_hash() ?>',cat={},tabla,modal;
 const wait=title=>Swal.fire({title,text:'Espere un momento…',allowOutsideClick:false,allowEscapeKey:false,didOpen:()=>Swal.showLoading()});const done=()=>Swal.close();const safe=v=>$.fn.dataTable.render.text().display(v==null?'':String(v));
 async function request(url,method='GET',data=null){const opts={method,headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}};if(data){data[csrfName]=csrfHash;opts.headers['Content-Type']='application/x-www-form-urlencoded;charset=UTF-8';opts.body=new URLSearchParams(data);}const res=await fetch(url,opts),j=await res.json();if(j.csrfHash)csrfHash=j.csrfHash;if(!res.ok||j.status==='error')throw new Error(j.message||'No se pudo completar la operación.');return j;}
 function llenar(select,items,value,label){select.innerHTML='<option value="">Seleccione...</option>';for(const x of items)select.append(new Option(label(x),x[value]));}
 function relaciones(est,actual=null){const list=cat.relaciones.filter(x=>!est||String(x.eup_est_ide)===String(est));if(actual&&!list.some(x=>String(x.eup_ide)===String(actual.eup_ide)))list.push(actual);llenar(document.getElementById('eus_eup_ide'),list,'eup_ide',x=>`${x.ups_codigo?x.ups_codigo+' · ':''}${x.ups_nombre}${x.est_nombre?' — '+x.est_nombre:''}`);const sel=document.getElementById('eus_eup_ide');sel.disabled=!list.length;}
 function servicios(eupId,actual=null,soloActivos=false){const parent=cat.relaciones.find(x=>String(x.eup_ide)===String(eupId))||actual;const upsId=parent?.eup_ups_ide;const coinciden=cat.servicios.filter(s=>String(s.uss_ups_ide)===String(upsId));let list=soloActivos?coinciden.filter(s=>Number(s.uss_estado)===1&&Number(s.ups_estado)===1):coinciden;if(actual&&!list.some(s=>String(s.uss_ide)===String(actual.eus_uss_ide)))list.push({uss_ide:actual.eus_uss_ide,uss_ups_ide:upsId,uss_codigo:actual.uss_codigo,uss_nombre:actual.uss_nombre,uss_estado:0,ups_estado:0});const select=document.getElementById('eus_uss_ide');llenar(select,list,'uss_ide',s=>`${s.uss_codigo?s.uss_codigo+' · ':''}${s.uss_nombre}${Number(s.uss_estado)===1&&Number(s.ups_estado)===1?'':' (inactivo)'}`);if(!list.length){const activos=cat.servicios.filter(s=>Number(s.uss_estado)===1&&Number(s.ups_estado)===1).length;const motivo=coinciden.length?'Los servicios de esta UPSS están inactivos':activos?'No hay servicios activos vinculados a esta UPSS. Verifique que uss_ups_ide corresponda a la UPSS seleccionada.':'No hay servicios UPSS activos registrados';select.innerHTML=`<option value="">${motivo}</option>`;}select.disabled=!list.length;}
 function crearTabla(){tabla=$('#tablaEus').DataTable({ajax:{url:api,data:d=>{d.establecimiento=$('#filtroEusEst').val();d.estado=$('#filtroEusEstado').val();},dataSrc:'data'},columns:[{data:'eus_ide'},{data:null,render:(v,t,r)=>t==='display'?`${r.est_ipress?`<span class="text-muted">${safe(r.est_ipress)}</span> · `:''}${safe(r.est_nombre)}`:r.est_nombre},{data:'red_nombre',render:v=>safe(v||'-')},{data:null,render:(v,t,r)=>t==='display'?`${safe(r.ups_codigo||'')} ${safe(r.ups_nombre)}`.trim():r.ups_nombre},{data:null,render:(v,t,r)=>t==='display'?`${safe(r.uss_codigo||'')} ${safe(r.uss_nombre)}`.trim():r.uss_nombre},{data:'eus_observacion',render:v=>safe(v||'-')},{data:'eus_estado',render:v=>Number(v)===1?'<span class="badge bg-success-subtle text-success">Activo</span>':'<span class="badge bg-secondary-subtle text-secondary">Inactivo</span>'},{data:'updated_at',render:v=>safe(v?v.split(' ')[0]:'-')},{data:null,orderable:false,searchable:false,className:'text-end',render:(v,t,r)=>t==='display'?`<button type="button" class="btn btn-outline-primary btn-sm js-edit" data-id="${r.eus_ide}" title="Editar" aria-label="Editar"><iconify-icon icon="lucide:edit-2"></iconify-icon></button> <button type="button" class="btn btn-outline-danger btn-sm js-delete" data-id="${r.eus_ide}" title="Eliminar" aria-label="Eliminar"><iconify-icon icon="lucide:trash-2"></iconify-icon></button>`:''}],order:[[1,'asc'],[3,'asc']],pageLength:25,language:{search:'Buscar:',lengthMenu:'Mostrar _MENU_ registros',zeroRecords:'No se encontraron asignaciones',emptyTable:'No hay servicios asignados',info:'Mostrando _START_ a _END_ de _TOTAL_',paginate:{first:'Primero',last:'Último',next:'Siguiente',previous:'Anterior'}}});$('#tablaEus').on('click','.js-edit',editar).on('click','.js-delete',eliminar);}
 async function inicio(){wait('Cargando catálogos');try{cat=await request(root.dataset.catalogos);llenar(document.getElementById('filtroEusEst'),cat.establecimientos,'est_ide',e=>(e.est_ipress?e.est_ipress+' · ':'')+e.est_nombre);llenar(document.getElementById('eus_est_ide'),cat.establecimientos,'est_ide',e=>(e.est_ipress?e.est_ipress+' · ':'')+e.est_nombre);done();modal=new bootstrap.Modal(document.getElementById('modalEus'));crearTabla();}catch(e){done();Swal.fire({icon:'error',title:'Error al cargar catálogos',text:e.message});}}
 $('#filtroEusEst,#filtroEusEstado').on('change',()=>tabla?.ajax.reload());$('#eus_est_ide').on('change',e=>{relaciones(e.target.value);servicios('');});$('#eus_eup_ide').on('change',e=>servicios(e.target.value,null,true));
 $('#btnNuevoEus').on('click',()=>{$('#formEus')[0].reset();$('#eus_ide').val('');$('#eus_estado').prop('checked',true);$('#eus_est_ide,#eus_eup_ide,#eus_uss_ide').prop('disabled',false);relaciones('');servicios('');$('#tituloEus').text('Asignar servicio a UPSS del establecimiento');modal.show();});
 async function editar(){const row=tabla.row($(this).closest('tr')).data();$('#formEus')[0].reset();$('#eus_ide').val(row.eus_ide);$('#eus_est_ide').val(String(row.est_ide));relaciones(row.est_ide,row);$('#eus_eup_ide').val(String(row.eus_eup_ide));servicios(row.eus_eup_ide,row,false);$('#eus_uss_ide').val(String(row.eus_uss_ide));$('#eus_observacion').val(row.eus_observacion||'');$('#eus_estado').prop('checked',Number(row.eus_estado)===1);$('#tituloEus').text('Editar asignación de servicio');modal.show();}
 $('#formEus').on('submit',async function(ev){ev.preventDefault();if(!this.reportValidity())return;const id=$('#eus_ide').val(),d={eus_eup_ide:$('#eus_eup_ide').val(),eus_uss_ide:$('#eus_uss_ide').val(),eus_observacion:$('#eus_observacion').val(),eus_estado:$('#eus_estado').is(':checked')?'1':'0'};$('#btnGuardarEus').prop('disabled',true);wait(id?'Actualizando asignación':'Guardando asignación');try{const res=await request(id?`${api}/${id}`:api,id?'PUT':'POST',d);done();modal.hide();Swal.fire({icon:'success',title:'Guardado',text:res.message});tabla.ajax.reload(null,false);}catch(e){done();Swal.fire({icon:'error',title:'No se pudo guardar',text:e.message});}finally{$('#btnGuardarEus').prop('disabled',false);$('#formEus input[name="'+csrfName+'"]').val(csrfHash);}});
 async function eliminar(){const id=$(this).data('id');const confirm=await Swal.fire({icon:'warning',title:'¿Archivar el servicio?',text:'Se conservará el historial de programaciones.',showCancelButton:true,confirmButtonText:'Archivar',cancelButtonText:'Cancelar',confirmButtonColor:'#dc3545'});if(!confirm.isConfirmed)return;wait('Archivando servicio');try{const r=await request(`${api}/${id}`,'DELETE',{});done();Swal.fire({icon:'success',title:'Archivado',text:r.message});tabla.ajax.reload(null,false);}catch(e){done();Swal.fire({icon:'error',title:'No se pudo archivar',text:e.message});}}
 document.addEventListener('DOMContentLoaded',inicio);
})();
</script>
<?= $this->endSection() ?>
